insert into public.blocks (page_id, type, label, sort, data)
select p.id, b->>'type', b->>'label', (t.i - 1)::int, b->'data'
from public.pages p,
     jsonb_array_elements($concept$[{"type":"gidsKop","label":"Kop","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Gids · Zieke werknemer","kruimel":"Zieke werknemer","heading":"Zieke werknemer: wat moet je als werkgever doen?","antwoord":"Meldt een werknemer zich ziek, dan leg je de ziekmelding vast, houd je contact, meld je het binnen een week bij je arbodienst en betaal je het loon door, minimaal 70 procent. Je mag vragen wanneer iemand terug verwacht te zijn en wat je kunt doen, maar niet wat iemand mankeert: dat is aan de bedrijfsarts.","text":"Deze gids loopt de eerste dag, de eerste week en de eerste zes weken langs: wat je regelt, wat je mag vragen, wat je medewerker moet doen en wanneer de arbodienst in beeld komt.","auteur":{"naam":"Rens van Eyck","functie":"Bestuurder van React2u"},"gepubliceerd":"2026-11-24","bijgewerkt":"2026-11-24"}},{"type":"gidsTekst","label":"De eerste dag","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"De eerste dag: de ziekmelding","tekst":"De meeste ziekmeldingen zijn kort: een griep, een rugklacht, een paar dagen thuis. Toch begint op de eerste ziektedag de telling van alle termijnen, dus doe de eerste dag goed.\n\n- **Leg de ziekmelding vast** met de datum en het tijdstip. In je verzuimprotocol staat hoe en bij wie een medewerker zich ziek meldt, meestal telefonisch bij de leidinggevende vóór een vast tijdstip.\n- **Vraag wat je mag vragen**: hoe lang iemand verwacht ziek te zijn, of er lopende afspraken of taken zijn die overgenomen moeten worden, op welk adres en nummer iemand bereikbaar is, en of de ziekte te maken heeft met een ongeval waarvoor een ander aansprakelijk is. Dat laatste is van belang voor het verhalen van de loonschade.\n- **Vraag niet** wat iemand mankeert. Vertelt je medewerker het uit zichzelf, dan mag je dat niet vastleggen. De Autoriteit Persoonsgegevens is daar streng in.\n- **Toon aandacht**. Een kort, oprecht gesprek op dag één doet meer voor het herstel dan welk formulier ook.\n\nMeld de ziekte **bij je arbodienst** zodra dat kan. De wet zegt uiterlijk binnen een week; bij React2u meld je op de eerste dag en belt je casemanager binnen één werkdag met jou en je medewerker. Zo weet je snel of het bij een paar dagen blijft of dat begeleiding nodig is.","kader":{"eyebrow":"Begrip","titel":"Loondoorbetaling","tekst":"Bij ziekte betaal je maximaal twee jaar loon door: minimaal 70 procent, in het eerste jaar nooit minder dan het minimumloon. Veel cao’s schrijven meer voor, vaak 100 procent in het eerste jaar. Een of twee wachtdagen mogen alleen als ze in je cao of arbeidsovereenkomst staan.","href":"/wet-verbetering-poortwachter","label":"Alle termijnen van de wet"}}},{"type":"gidsTijdlijn","label":"De eerste zes weken","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Stappenplan","heading":"De eerste zes weken na de ziekmelding","text":"Wat er wanneer gebeurt als het verzuim langer duurt dan een paar dagen. De weken tellen vanaf de eerste ziektedag.","items":[{"wanneer":"Dag 1","titel":"Ziekmelding en eerste contact","wie":"Werkgever","tekst":"Je legt de melding vast, vraagt wat je mag vragen en spreekt af wanneer jullie weer contact hebben. Je meldt de ziekte bij je arbodienst."},{"wanneer":"Dag 2","titel":"Contact met de casemanager","wie":"Casemanager","tekst":"De casemanager belt met jou en met je medewerker: wat speelt er, wat is er nodig, is een spreekuur bij de bedrijfsarts nodig? Alles zonder medische details richting jou."},{"wanneer":"Week 1","titel":"Afspraken over contact en werk","wie":"Werkgever en werknemer","tekst":"Hoe vaak bellen jullie, wie neemt het werk over, en zijn er taken die je medewerker wél kan doen? Leg het kort vast."},{"wanneer":"Week 2 tot 4","titel":"Spreekuur bij de bedrijfsarts","wie":"Bedrijfsarts","tekst":"Duurt het langer, dan ziet de bedrijfsarts je medewerker op het spreekuur. Jij krijgt een terugkoppeling met de beperkingen en mogelijkheden, niet de diagnose."},{"wanneer":"Week 4","titel":"Eerste beeld van de duur","wie":"Casemanager","tekst":"Verwacht de bedrijfsarts een kort of een langer verzuim? Met dat beeld plan je de volgende stappen en, als dat nodig is, het eerste gesprek over werkhervatting."},{"wanneer":"Week 6","titel":"Probleemanalyse","wie":"Bedrijfsarts","tekst":"Is je medewerker na zes weken nog ziek, dan maakt de bedrijfsarts de probleemanalyse: wat kan je medewerker nog, wat is de verwachting en welk advies geldt. De eerste harde termijn van de Wet verbetering poortwachter."},{"wanneer":"Week 8","titel":"Plan van aanpak","wie":"Werkgever en werknemer","tekst":"Op basis van de probleemanalyse spreken jullie af wat het doel is en hoe je daar komt. Vanaf hier loopt het traject van de wet; lees de gids over de Wet verbetering poortwachter."}],"noot":"Is je medewerker eerder beter, dan meld je dat als hersteld bij de arbodienst en stopt het traject. Wordt hij of zij binnen vier weken opnieuw ziek, dan tellen de periodes bij elkaar op."}},{"type":"gidsTekst","label":"Wat je mag vragen","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat je wel en niet mag vragen en vastleggen","tekst":"Hier gaat het vaak mis, niet uit kwade wil maar uit betrokkenheid. Je wilt weten hoe het met iemand gaat. Dat mag je vragen als mens; als werkgever mag je er niets mee doen. De regels van de Autoriteit Persoonsgegevens:\n\n### Wel vragen en vastleggen\n\n- het telefoonnummer en adres waar je medewerker bereikbaar is\n- de verwachte duur van het verzuim\n- de lopende afspraken en werkzaamheden die overgenomen moeten worden\n- of de ziekte onder een vangnet valt, zoals de Ziektewet bij zwangerschap of orgaandonatie, zonder de reden erachter\n- of er een ongeval is waarvoor een derde aansprakelijk is\n- wat je medewerker nog wél kan, volgens de bedrijfsarts\n\n### Niet vragen, en nooit vastleggen\n\n- de aard en oorzaak van de ziekte\n- de behandeling, de medicatie, de arts of het ziekenhuis\n- wat je medewerker in vertrouwen vertelt, ook niet als notitie in het dossier\n\nDe bedrijfsarts mag dit allemaal wél weten en beoordeelt daarmee wat je medewerker kan. Jij krijgt het advies: de beperkingen, de mogelijkheden, de verwachte duur. Dat is genoeg om te sturen, en het beschermt jou ook: een werkgever die medische gegevens vastlegt, overtreedt de AVG.","kader":{"eyebrow":"Voor je medewerker","titel":"Ziek, wat nu?","tekst":"Op de werknemerspagina staat wat je medewerker zelf moet doen en mag verwachten: bereikbaar zijn, meewerken aan herstel, en het recht op privacy bij de bedrijfsarts.","href":"/verzuimprotocol","label":"Lees het verzuimprotocol"}}},{"type":"gidsTabel","label":"Wie doet wat","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Op een rij","heading":"Wie doet wat bij een ziekmelding","text":"De eerste zes weken in één tabel: wat jij doet, wat je medewerker doet en wat de arbodienst doet.","kolommen":["Moment","Werkgever","Werknemer","Arbodienst"],"rijen":[["Dag 1","Ziekmelding vastleggen, contact afspreken, loondoorbetaling regelen","Ziek melden volgens het protocol, bereikbaar zijn","Melding ontvangen, dossier openen"],["Dag 2","Werk herverdelen, aandacht tonen","Vragen van de casemanager beantwoorden","Casemanager belt werkgever en werknemer"],["Week 1","Melding bij de arbodienst (uiterlijk)","Meewerken aan herstel, afspraken nakomen","Inschatten of een spreekuur nodig is"],["Week 2 tot 4","Contact houden, vastleggen wat is besproken","Naar het spreekuur van de bedrijfsarts","Spreekuur en terugkoppeling aan de werkgever"],["Week 6","Probleemanalyse ontvangen en lezen","Meewerken aan de probleemanalyse","Bedrijfsarts maakt de probleemanalyse"],["Week 8","Plan van aanpak opstellen en tekenen, casemanager aanwijzen","Plan van aanpak meemaken en tekenen","Casemanager begeleidt het plan en bewaakt de termijnen"]],"noot":"De termijnen daarna (elke zes weken evalueren, week 42, week 52 en verder) staan in de gids over de Wet verbetering poortwachter en in de Poortwachter-planner."}},{"type":"gidsTekst","label":"Wat je medewerker moet doen","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat je medewerker moet doen, en wat je kunt doen als dat niet gebeurt","tekst":"Ziekte is geen vrijbrief. Je medewerker heeft verplichtingen, en jij mag daarop aanspreken:\n\n- zich ziek melden volgens het protocol, op tijd en bij de juiste persoon\n- bereikbaar zijn en controlevoorschriften naleven, zoals verschijnen bij de bedrijfsarts\n- meewerken aan herstel: behandelingen volgen, niets doen wat het herstel vertraagt\n- passend werk accepteren als de bedrijfsarts zegt dat dat kan\n- meewerken aan het plan van aanpak en de re-integratie\n\nGebeurt dat niet, dan heb je twee middelen, beide pas na een **schriftelijke waarschuwing**:\n\n- **Loonopschorting** als je medewerker controlevoorschriften niet naleeft, bijvoorbeeld niet verschijnt bij de bedrijfsarts. Het loon wordt alsnog betaald zodra hij of zij weer meewerkt.\n- **Loonstop** als je medewerker passend werk weigert of niet meewerkt aan de re-integratie. Dat loon is definitief weg.\n\nOverleg altijd eerst met je casemanager. Een loonmaatregel die niet klopt, keert zich tegen je bij de rechter en bij UWV. En vaak werkt een goed gesprek beter: de meeste medewerkers die niet meewerken, zijn bang of boos, niet onwillig.\n\nTwijfel je of je medewerker echt niet kan werken, of is hij of zij het oneens met het oordeel van de bedrijfsarts? Dan is er het **deskundigenoordeel** van UWV: een onafhankelijk oordeel, voor een werkgever 400 euro, voor een werknemer 100 euro.","kader":{"eyebrow":"Goed om te weten","titel":"Ziek tijdens vakantie of ontslag","tekst":"Wordt je medewerker ziek tijdens vakantie, dan gelden die dagen als ziektedagen, niet als vakantie, mits de ziekmelding volgens het protocol is gedaan. Tijdens ziekte geldt een opzegverbod van twee jaar; een ziekmelding ná een aangekondigd ontslag valt daar niet onder."}}},{"type":"gidsVragen","label":"Veelgestelde vragen","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Veelgestelde vragen","heading":"Vragen over een zieke werknemer","text":"Staat je vraag er niet bij? Bel ons gerust, ook als je nog geen klant bent.","items":[{"question":"Mag ik vragen wat mijn medewerker mankeert?","answer":"Nee. Je mag vragen hoe lang het verzuim naar verwachting duurt, waar iemand bereikbaar is en welk werk overgenomen moet worden. De aard van de ziekte is aan de bedrijfsarts; vertelt je medewerker het uit zichzelf, dan mag je het niet vastleggen."},{"question":"Moet ik het loon doorbetalen vanaf de eerste dag?","answer":"Ja, minimaal 70 procent en in het eerste jaar minstens het minimumloon, tenzij je cao of arbeidsovereenkomst een of twee wachtdagen toestaat. Veel cao’s schrijven 100 procent voor in het eerste jaar."},{"question":"Wanneer moet ik de ziekmelding doorgeven aan de arbodienst?","answer":"Uiterlijk binnen een week na de eerste ziektedag. Hoe eerder, hoe beter: dan kan de casemanager meteen contact opnemen en weet je snel of begeleiding nodig is. Bij React2u meld je op dag één."},{"question":"Mag mijn medewerker thuis blijven zonder naar de bedrijfsarts te gaan?","answer":"Nee. Verschijnen op het spreekuur van de bedrijfsarts hoort bij de verplichtingen van je medewerker. Blijft hij of zij zonder goede reden weg, dan mag je na een schriftelijke waarschuwing het loon opschorten."},{"question":"Wat als mijn medewerker ziek is door een arbeidsconflict?","answer":"Dan adviseert de bedrijfsarts meestal een korte afkoelingsperiode en een gesprek, soms met een mediator. Een conflict is geen ziekte, maar kan wel tot klachten leiden; de bedrijfsarts beoordeelt wat er speelt."},{"question":"Mag ik een zieke medewerker ontslaan?","answer":"In de eerste twee ziektejaren geldt een opzegverbod. Uitzonderingen zijn een ontslag op staande voet om een dringende reden, een faillissement, het aflopen van een tijdelijk contract of een ziekmelding na het aankondigen van het ontslag."},{"question":"Hoe vaak moet ik contact houden met een zieke medewerker?","answer":"De wet noemt geen aantal, maar regelmatig contact is de basis van elke re-integratie en van het dossier. Spreek op dag één af hoe vaak jullie bellen, bijvoorbeeld wekelijks, en leg kort vast wat is besproken."}]}},{"type":"gidsHelpt","label":"Zo helpt React2u","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Zo helpt React2u","heading":"Op dag één weten waar je aan toe bent","tekst":"Je meldt je medewerker ziek bij React2u, en binnen één werkdag belt je vaste casemanager met jou en je medewerker. De bedrijfsarts is snel beschikbaar, de termijnen staan in het dossier en jij hoort alleen wat je nodig hebt om te sturen. Zo blijft een korte ziekmelding kort, en begint een langere meteen goed.","punten":["Ziekmelden op dag één, telefonisch of online","Binnen één werkdag contact met werkgever en werknemer","Spreekuur bij de bedrijfsarts binnen een paar dagen","Elke termijn bewaakt in het online dossier"],"dienst":{"naam":"Recover","wat":"Verzuimbegeleiding voor werkgevers","tekst":"Casemanagement, bedrijfsarts en taakdelegatie, poortwachterdossier en UWV.","href":"/recover","label":"Meer over React2u Recover"},"kennismaken":{"label":"Kennismaken","href":"/kennismaken"},"belTekst":"Of bel 085 620 58 00, ma t/m vr 9.00 tot 17.00 uur.","verwant":[{"label":"Gids: Wet verbetering poortwachter","href":"/wet-verbetering-poortwachter"},{"label":"Gids: de bedrijfsarts","href":"/bedrijfsarts"},{"label":"Poortwachter-planner","href":"/kennis/poortwachter-planner"},{"label":"Medewerker langdurig ziek? Dit moet je weten","href":"/blog/medewerker-langdurig-ziek"}]}},{"type":"homeContact","label":"Contact","data":{"eyebrow":"Contact","heading":"Een vraag?\nBel gewoon even.","text":"Bel van maandag tot en met vrijdag tussen 9.00 en 17.00 uur, dan neemt een van ons op.","image":"/beeld/home/even-bellen.webp","alt":"Een vrouw belt ontspannen met React2u","focus":"52% 22%","routes":[{"icon":"phone","label":"Bellen · ma t/m vr 9.00 tot 17.00 uur","value":"085 620 58 00","href":"tel:+31856205800"},{"icon":"mail","label":"Mailen","value":"info@react2u.nl","href":"mailto:info@react2u.nl"},{"icon":"clock","label":"Liever teruggebeld?","value":"Plan een terugbelmoment","href":"/contact"}],"bg":"#ffffff"}}]$concept$::jsonb) with ordinality as t(b, i)
where p.slug = 'zieke-werknemer';

update public.pages
set updated_at = now(),
    published = true
where slug = 'zieke-werknemer';

