insert into public.blocks (page_id, type, label, sort, data)
select p.id, b->>'type', b->>'label', (t.i - 1)::int, b->'data'
from public.pages p,
     jsonb_array_elements($concept$[{"type":"gidsKop","label":"Kop","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Gids · Casemanager verzuim","kruimel":"Casemanager verzuim","heading":"Wat doet een casemanager verzuim?","antwoord":"Een casemanager verzuim is het vaste aanspreekpunt in een verzuimtraject: hij of zij houdt contact met jou en je werknemer, bewaakt de termijnen van de Wet verbetering poortwachter, plant de bedrijfsarts in en zorgt dat het dossier compleet is voor UWV. De bedrijfsarts beoordeelt wat je werknemer kan; de casemanager zorgt dat er iets mee gebeurt.","text":"Deze gids legt uit wat de casemanager precies doet, hoe de rol verschilt van de bedrijfsarts, wat taakdelegatie en regie inhouden, wat een register casemanager is en wat jij als werkgever ervan merkt.","auteur":{"naam":"Rens van Eyck","functie":"Bestuurder van React2u"},"gepubliceerd":"2026-11-24","bijgewerkt":"2026-11-24"}},{"type":"gidsTekst","label":"Wat doet de casemanager","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Wat een casemanager verzuim doet","tekst":"De Wet verbetering poortwachter zegt dat werkgever en werknemer bij het plan van aanpak een casemanager aanwijzen: iemand die het traject coördineert. Dat mag een leidinggevende of een HR-medewerker zijn, maar de meeste werkgevers kiezen de casemanager van hun arbodienst, omdat die het vak kent en de termijnen in het systeem heeft.\n\nIn de praktijk doet de casemanager dit:\n\n- **Contact houden**: na de ziekmelding belt de casemanager met jou en met je werknemer, en daarna regelmatig. Hoe gaat het, wat is er nodig, wat is er veranderd?\n- **Termijnen bewaken**: de probleemanalyse in week 6, het plan van aanpak in week 8, de evaluaties elke zes weken, de 42e-weeksmelding, de eerstejaarsevaluatie, het re-integratieverslag. De casemanager weet wat er wanneer moet en herinnert je op tijd.\n- **De bedrijfsarts inplannen** en de terugkoppeling van het spreekuur naar jou vertalen: wat betekent dit advies voor het werk?\n- **Het dossier bijhouden**: elk gesprek, elke afspraak, elk document op datum, zodat UWV na twee jaar een compleet re-integratieverslag ziet.\n- **Adviseren**: over passend werk, een opbouwschema, een arbeidsdeskundig onderzoek, het tweede spoor, een deskundigenoordeel. En over wat je beter niet doet.\n- **Specialisten inschakelen**: een arbeidsdeskundige, een psycholoog, een fysiotherapeut of een re-integratiebegeleider, als het traject daarom vraagt.\n\nDe casemanager is geen arts en krijgt niet vanzelf medische informatie. Wat hij of zij wel ziet, hangt af van de werkwijze: onder taakdelegatie van de bedrijfsarts meer, in de regierol niets medisch. Daarover hieronder meer.","kader":{"eyebrow":"Voor je werknemer","titel":"Je casemanager, vanuit de werknemer gezien","tekst":"Op de werknemerspagina staat wat een zieke werknemer van de casemanager mag verwachten: aandacht, duidelijkheid over de stappen en het recht om medische zaken alleen met de bedrijfsarts te bespreken.","href":"/je-casemanager","label":"Lees de werknemerspagina"}}},{"type":"gidsTekst","label":"Taakdelegatie of regie","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Taakdelegatie of regie: twee soorten casemanagers","tekst":"Er zijn twee manieren waarop een casemanager werkt, en het verschil zit in de medische informatie.\n\n### Casemanager onder taakdelegatie\n\nDe bedrijfsarts draagt taken over aan de casemanager, bijvoorbeeld het verzuimspreekuur en het uitvragen van klachten en beperkingen. De casemanager werkt dan onder verantwoordelijkheid van de bedrijfsarts, heeft dezelfde geheimhoudingsplicht en mag medische informatie zien en vastleggen in het medisch dossier. De bedrijfsarts blijft eindverantwoordelijk, bekijkt elk dossier en neemt de medische beslissingen. Voor jou als werkgever betekent dit: sneller contact, vaker een gesprek, en een lager tarief dan de bedrijfsarts.\n\n### Casemanager in de regierol\n\nDe casemanager werkt voor de werkgever, zonder medische informatie. Hij of zij stuurt op het proces: de termijnen, de afspraken, het dossier, het contact. Medische vragen gaan naar de bedrijfsarts; de casemanager krijgt het advies, niet de diagnose. Dit is de rol die de wet bedoelt met de casemanager in het plan van aanpak.\n\nBeide rollen bestaan naast elkaar en in de praktijk werken ze samen: een praktijkondersteuner onder taakdelegatie doet het spreekuur, de regiecasemanager bewaakt het traject. Wat voor jou telt: vraag je arbodienst hoe het geregeld is en wie je waarvoor belt. En weet dat jij nooit medische informatie hoort te krijgen, van geen van beiden."}},{"type":"gidsTijdlijn","label":"In een traject","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Wet verbetering poortwachter","heading":"De casemanager in een verzuimtraject","text":"Wat de casemanager op elk moment doet, en wat jij ervan merkt. De weken tellen vanaf de eerste ziektedag.","items":[{"wanneer":"Dag 1 tot 2","titel":"Eerste contact","wie":"Casemanager","tekst":"Binnen één werkdag na de ziekmelding belt de casemanager met jou en je werknemer. Wat speelt er, wat is er nodig, is een spreekuur nodig? Je weet meteen bij wie je terechtkunt."},{"wanneer":"Week 1 tot 6","titel":"Contact en spreekuur","wie":"Casemanager en bedrijfsarts","tekst":"De casemanager houdt contact, plant het spreekuur bij de bedrijfsarts en vertaalt de terugkoppeling: wat betekent het advies voor het werk? Jij hoort wat je nodig hebt, zonder diagnose."},{"wanneer":"Week 6","titel":"Probleemanalyse","wie":"Bedrijfsarts","tekst":"De casemanager zorgt dat de probleemanalyse er op tijd is en bespreekt met jou wat erin staat en wat de volgende stap is."},{"wanneer":"Week 8","titel":"Plan van aanpak","wie":"Werkgever en werknemer, met de casemanager","tekst":"De casemanager helpt het plan schrijven: concreet, haalbaar, met evaluatiemomenten. Jullie tekenen; de casemanager wordt als casemanager in het plan genoemd."},{"wanneer":"Elke 6 weken","titel":"Evaluatie","wie":"Casemanager","tekst":"De casemanager plant de evaluaties, zit erbij of bereidt ze voor, legt de uitkomst vast en stelt het plan bij. Het ritme dat UWV wil zien."},{"wanneer":"Week 42 tot 52","titel":"Melding, onderzoek en eerstejaarsevaluatie","wie":"Casemanager","tekst":"De 42e-weeksmelding wordt voorbereid, een arbeidsdeskundig onderzoek geadviseerd als terugkeer onzeker is, en de eerstejaarsevaluatie op tijd gepland met een onderbouwde keuze voor het spoor."},{"wanneer":"Week 52 tot 104","titel":"Tweede spoor en WIA","wie":"Casemanager en re-integratiebegeleider","tekst":"De casemanager zet het tweede spoor in gang, bewaakt de rapportages en stelt tegen het einde het re-integratieverslag samen uit alles wat in het dossier staat."}]}},{"type":"gidsTabel","label":"Casemanager en bedrijfsarts","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Op een rij","heading":"Casemanager, bedrijfsarts en jij: wie doet wat","text":"De rollen vullen elkaar aan en vervangen elkaar niet.","kolommen":["Onderwerp","Casemanager","Bedrijfsarts","Werkgever"],"rijen":[["Medisch oordeel","Nee (onder taakdelegatie: uitvragen namens de bedrijfsarts)","Ja: beperkingen, mogelijkheden, prognose","Nooit"],["Contact met de werknemer","Regelmatig, over het proces en het werk","Op het spreekuur, over gezondheid en werk","Regelmatig, over het werk en het team"],["Termijnen","Bewaakt ze en herinnert op tijd","Levert de probleemanalyse en het actueel oordeel","Is eindverantwoordelijk"],["Plan van aanpak","Helpt schrijven en bijstellen","Adviseert over belastbaarheid","Stelt op en tekent, met de werknemer"],["Dossier","Houdt het bij, op datum en compleet","Houdt het medisch dossier apart","Bewaart het re-integratiedossier"],["Advies","Over stappen, passend werk, onderzoeken, tweede spoor","Over werkhervatting en aanpassingen","Beslist, op basis van beide"],["Tarief","In het verzuimabonnement, per werknemer per jaar","Per uur","Betaalt het loon door"]],"noot":"Bij React2u zit het casemanagement in het verzuimabonnement; de bedrijfsarts reken je per uur, net als de ondersteuner onder taakdelegatie tegen een lager tarief. Zie de prijslijst."}},{"type":"gidsTekst","label":"Register en kwaliteit","data":{"kleur":"#E61674","tint":"#FDECF4","heading":"Waar herken je een goede casemanager aan?","tekst":"Casemanager is geen beschermde titel; iedereen mag zich zo noemen. Een paar dingen zeggen wel iets:\n\n- **Een registratie**. Een register casemanager heeft een erkende opleiding gevolgd en houdt zijn kennis bij; de registers (zoals het RNVC) stellen eisen aan opleiding en bijscholing. Vraag ernaar.\n- **Eén vast gezicht**. Een casemanager die je organisatie kent, weet welke functies er zijn, welke leidinggevende moeite heeft met het gesprek en waar passend werk te vinden is. Een wisselend team begint elke keer opnieuw.\n- **Snelheid**. Contact binnen één werkdag na een ziekmelding; het verschil tussen een korte en een lange ziekmelding wordt vaak in de eerste week gemaakt.\n- **Duidelijkheid over medische informatie**. Een goede casemanager legt uit wat jij wel en niet te horen krijgt, en houdt zich daaraan.\n- **Eerlijkheid**. Ook als het advies is om het tweede spoor te starten terwijl jij nog hoopt op herstel, of om een loonmaatregel juist niet te nemen.\n\nEn kijk naar de omgeving: een casemanager is zo goed als de bedrijfsarts, de arbeidsdeskundige en het systeem erachter. Een gecertificeerde arbodienst met korte lijnen tussen die drie levert meer op dan een losse casemanager, hoe goed ook.","kader":{"eyebrow":"Goed om te weten","titel":"Zelf casemanager zijn?","tekst":"Het mag: een HR-medewerker of leidinggevende als casemanager in het plan van aanpak. Het vraagt wel kennis van de termijnen en tijd om het dossier bij te houden. De meeste werkgevers laten de arbodienst het doen en houden zelf het contact met de werknemer warm."}}},{"type":"gidsVragen","label":"Veelgestelde vragen","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Veelgestelde vragen","heading":"Vragen over de casemanager verzuim","text":"Staat je vraag er niet bij? Bel ons gerust, ook als je nog geen klant bent.","items":[{"question":"Is een casemanager verplicht?","answer":"De Wet verbetering poortwachter vraagt dat werkgever en werknemer bij het plan van aanpak een casemanager aanwijzen die het traject coördineert. Wie dat is, mag je zelf bepalen: iemand van de arbodienst, van HR of een leidinggevende."},{"question":"Krijgt de casemanager medische informatie?","answer":"Alleen onder taakdelegatie van de bedrijfsarts, met dezelfde geheimhoudingsplicht. Een casemanager in de regierol krijgt het advies van de bedrijfsarts, niet de diagnose. Jij als werkgever krijgt in geen van beide gevallen medische informatie."},{"question":"Wat is het verschil tussen een casemanager en een bedrijfsarts?","answer":"De bedrijfsarts is een arts en beoordeelt de belastbaarheid. De casemanager is geen arts en stuurt het proces: contact, termijnen, dossier, afspraken. De een zegt wat kan, de ander zorgt dat het gebeurt."},{"question":"Hoe vaak heeft de casemanager contact met mijn medewerker?","answer":"Bij React2u binnen één werkdag na de ziekmelding en daarna in een ritme dat past bij het verzuim, van wekelijks tot elke paar weken, en altijd rond de termijnen van de wet."},{"question":"Mag mijn medewerker de casemanager weigeren?","answer":"Meewerken aan de verzuimbegeleiding hoort bij de verplichtingen van je medewerker, dus contact met de casemanager niet weigeren. Is er een klik- of vertrouwensprobleem, dan kan de arbodienst een andere casemanager toewijzen; vraag ernaar."},{"question":"Wat is een register casemanager?","answer":"Een casemanager met een erkende opleiding die in een beroepsregister staat en zijn kennis bijhoudt. De titel casemanager zelf is niet beschermd; een registratie laat zien dat iemand het vak serieus neemt."},{"question":"Wat kost een casemanager?","answer":"Bij de meeste arbodiensten zit het casemanagement in het verzuimabonnement per werknemer per jaar; de bedrijfsarts en onderzoeken komen daar per uur of per stuk bij. Bij React2u staan de tarieven open op de prijslijst."}]}},{"type":"gidsHelpt","label":"Zo helpt React2u","data":{"kleur":"#E61674","tint":"#FDECF4","eyebrow":"Zo helpt React2u","heading":"Eén casemanager die je organisatie kent","tekst":"Bij React2u krijg je een vaste casemanager die jou en je mensen kent, binnen één werkdag belt na een ziekmelding en elke termijn in het dossier bewaakt. Samen met de bedrijfsarts en de praktijkondersteuner onder taakdelegatie: korte lijnen, snel contact, en een dossier dat compleet is voor UWV.","punten":["Eén vast gezicht, geen wisselend team","Contact binnen één werkdag met werkgever en werknemer","Taakdelegatie en regie onder één dak, met de bedrijfsarts erbij","Online dossier met alle termijnen en documenten"],"dienst":{"naam":"Recover","wat":"Verzuimbegeleiding voor werkgevers","tekst":"Casemanagement, bedrijfsarts en taakdelegatie, poortwachterdossier en UWV.","href":"/recover","label":"Meer over React2u Recover"},"kennismaken":{"label":"Kennismaken","href":"/kennismaken"},"belTekst":"Of bel 085 620 58 00, ma t/m vr 9.00 tot 17.00 uur.","verwant":[{"label":"Gids: de bedrijfsarts","href":"/bedrijfsarts"},{"label":"Gids: de arbodienst","href":"/arbodienst"},{"label":"Gids: Wet verbetering poortwachter","href":"/wet-verbetering-poortwachter"},{"label":"Je casemanager, voor werknemers","href":"/je-casemanager"}]}},{"type":"homeContact","label":"Contact","data":{"eyebrow":"Contact","heading":"Een vraag?\nBel gewoon even.","text":"Bel van maandag tot en met vrijdag tussen 9.00 en 17.00 uur, dan neemt een van ons op.","image":"/beeld/home/even-bellen.webp","alt":"Een vrouw belt ontspannen met React2u","focus":"52% 22%","routes":[{"icon":"phone","label":"Bellen · ma t/m vr 9.00 tot 17.00 uur","value":"085 620 58 00","href":"tel:+31856205800"},{"icon":"mail","label":"Mailen","value":"info@react2u.nl","href":"mailto:info@react2u.nl"},{"icon":"clock","label":"Liever teruggebeld?","value":"Plan een terugbelmoment","href":"/contact"}],"bg":"#ffffff"}}]$concept$::jsonb) with ordinality as t(b, i)
where p.slug = 'casemanager-verzuim';

update public.pages
set updated_at = now(),
    published = true
where slug = 'casemanager-verzuim';

